@Override
public void finalizeLayoutFeature(LayoutFeature lf, Object service) throws UpgradeException {
    Storage mockStorage = mock(Storage.class);
    InOrder inOrder = inOrder(mockStorage);
    super.finalizeLayoutFeature(lf, lf.action(LayoutFeature.UpgradeActionType.ON_FINALIZE), mockStorage);
    inOrder.verify(mockStorage).setLayoutVersion(ArgumentMatchers.eq(lf.layoutVersion()));
    try {
        inOrder.verify(mockStorage).persistCurrentState();
    } catch (IOException ex) {
        throw new UpgradeException(ex, UpgradeException.ResultCodes.LAYOUT_FEATURE_FINALIZATION_FAILED);
    }
    finalizeCalled = true;
}

