@Test
public void testContainerCloseActionWhenVolumeFull() throws Exception {
    String testDir = GenericTestUtils.getTempPath(TestHddsDispatcher.class.getSimpleName());
    OzoneConfiguration conf = new OzoneConfiguration();
    conf.setStorageSize(HddsConfigKeys.HDDS_DATANODE_VOLUME_MIN_FREE_SPACE, 100.0, StorageUnit.BYTES);
    DatanodeDetails dd = randomDatanodeDetails();
    HddsVolume.Builder volumeBuilder = new HddsVolume.Builder(testDir).datanodeUuid(dd.getUuidString()).conf(conf).usageCheckFactory(MockSpaceUsageCheckFactory.NONE);
    // state of cluster : available (140) > 100  ,datanode volume
    // utilisation threshold not yet reached. container creates are successful.
    SpaceUsageSource spaceUsage = fixed(500, 140, 360);
    SpaceUsageCheckFactory factory = MockSpaceUsageCheckFactory.of(spaceUsage, Duration.ZERO, inMemory(new AtomicLong(0)));
    volumeBuilder.usageCheckFactory(factory);
    MutableVolumeSet volumeSet = Mockito.mock(MutableVolumeSet.class);
    Mockito.when(volumeSet.getVolumesList()).thenReturn(Collections.singletonList(volumeBuilder.build()));
    try {
        UUID scmId = UUID.randomUUID();
        ContainerSet containerSet = new ContainerSet(1000);
        StateContext context = ContainerTestUtils.getMockContext(dd, conf);
        // create a 50 byte container
        KeyValueContainerData containerData = new KeyValueContainerData(1L, layout, 50, UUID.randomUUID().toString(), dd.getUuidString());
        Container container = new KeyValueContainer(containerData, conf);
        container.create(volumeSet, new RoundRobinVolumeChoosingPolicy(), scmId.toString());
        containerSet.addContainer(container);
        ContainerMetrics metrics = ContainerMetrics.create(conf);
        Map<ContainerType, Handler> handlers = Maps.newHashMap();
        for (ContainerType containerType : ContainerType.values()) {
            handlers.put(containerType, Handler.getHandlerForContainerType(containerType, conf, context.getParent().getDatanodeDetails().getUuidString(), containerSet, volumeSet, metrics, NO_OP_ICR_SENDER));
        }
        HddsDispatcher hddsDispatcher = new HddsDispatcher(conf, containerSet, volumeSet, handlers, context, metrics, null);
        hddsDispatcher.setClusterId(scmId.toString());
        containerData.getVolume().getVolumeInfo().ifPresent(volumeInfo -> volumeInfo.incrementUsedSpace(50));
        ContainerCommandResponseProto response = hddsDispatcher.dispatch(getWriteChunkRequest(dd.getUuidString(), 1L, 1L), null);
        Assert.assertEquals(ContainerProtos.Result.SUCCESS, response.getResult());
        verify(context, times(1)).addContainerActionIfAbsent(Mockito.any(ContainerAction.class));
        // try creating another container now as the volume used has crossed
        // threshold
        KeyValueContainerData containerData2 = new KeyValueContainerData(1L, layout, 50, UUID.randomUUID().toString(), dd.getUuidString());
        Container container2 = new KeyValueContainer(containerData2, conf);
        StorageContainerException scException = assertThrows(StorageContainerException.class, () -> container2.create(volumeSet, new RoundRobinVolumeChoosingPolicy(), scmId.toString()));
        assertEquals("Container creation failed, due to disk out of space", scException.getMessage());
    } finally {
        volumeSet.shutdown();
        ContainerMetrics.remove();
        FileUtils.deleteDirectory(new File(testDir));
    }
}

