public void testDeleteBlocksCommandHandler() throws IOException {
    Assert.assertTrue(containerSet.containerCount() > 0);
    Container<?> container = containerSet.getContainerIterator(volume1).next();
    DeletedBlocksTransaction transaction = createDeletedBlocksTransaction(1, container.getContainerData().getContainerID());
    List<DeleteBlockTransactionResult> results = handler.executeCmdWithRetry(Arrays.asList(transaction));
    String schemaVersionOrDefault = ((KeyValueContainerData) container.getContainerData()).getSupportedSchemaVersionOrDefault();
