@Test
public void testDeleteContainer() throws Exception {
    closeContainer();
    keyValueContainer = new KeyValueContainer(keyValueContainerData, CONF);
    keyValueContainer.create(volumeSet, volumeChoosingPolicy, scmId);
    KeyValueContainerUtil.removeContainer(keyValueContainer.getContainerData(), CONF);
    keyValueContainer.delete();
    String containerMetaDataPath = keyValueContainerData.getMetadataPath();
    File containerMetaDataLoc = new File(containerMetaDataPath);
    assertFalse("Container directory still exists", containerMetaDataLoc.getParentFile().exists());
    assertFalse("Container File still exists", keyValueContainer.getContainerFile().exists());
    if (isSameSchemaVersion(schemaVersion, OzoneConsts.SCHEMA_V3)) {
        assertTrue(keyValueContainer.getContainerDBFile().exists());
    } else {
        assertFalse("Container DB file still exists", keyValueContainer.getContainerDBFile().exists());
    }
}

