    // unhealthy.
    Mockito.when(mockVolume.isFailed()).thenReturn(false);
    handler.markContainerUnhealthy(container, ContainerTestUtils.getUnhealthyScanResult());
    Mockito.verify(mockIcrSender, Mockito.atMostOnce()).send(Mockito.any());
}

