    //recovering container should be deleted, so the count should be 2
    Assert.assertEquals(2, containerSet.containerCount());
    for (int i = 0; i < 2; i++) {
        Container keyValueContainer = containerSet.getContainer(i);
        KeyValueContainerData keyValueContainerData = (KeyValueContainerData) keyValueContainer.getContainerData();
        // Verify block related metadata.
        Assert.assertEquals(blockCount, keyValueContainerData.getBlockCount());
        Assert.assertEquals(blockCount * blockLen, keyValueContainerData.getBytesUsed());
        Assert.assertEquals(i, keyValueContainerData.getNumPendingDeletionBlocks());
    }
}

@Test
public void testMarkedDeletedContainerCleared() throws Exception {
    KeyValueContainerData containerData = new KeyValueContainerData(101, layout, (long) StorageUnit.GB.toBytes(5), UUID.randomUUID().toString(), datanodeId.toString());
    //create a container with deleted state
    containerData.setState(DELETED);
    KeyValueContainer kvContainer = new KeyValueContainer(containerData, conf);
    kvContainer.create(volumeSet, volumeChoosingPolicy, clusterId);
    long baseCount = 0;
    if (containerData.hasSchema(OzoneConsts.SCHEMA_V3)) {
        // add db entry for the container ID 101 for V3
        baseCount = addDbEntry(containerData);
    }
    ContainerReader containerReader = new ContainerReader(volumeSet, hddsVolume, containerSet, conf, false);
    containerReader.run();
    // assert that tmp dir is empty
    File[] leftoverContainers = hddsVolume.getDeletedContainerDir().listFiles();
    Assertions.assertNotNull(leftoverContainers);
    Assertions.assertEquals(0, leftoverContainers.length);
    Assertions.assertNull(containerSet.getContainer(101));
    if (containerData.hasSchema(OzoneConsts.SCHEMA_V3)) {
        // verify if newly added container is not present as added
        try (DBHandle dbHandle = BlockUtils.getDB(kvContainer.getContainerData(), conf)) {
            DatanodeStoreSchemaThreeImpl store = (DatanodeStoreSchemaThreeImpl) dbHandle.getStore();
            Assertions.assertEquals(baseCount, store.getMetadataTable().getEstimatedKeyCount());
        }
    }
}

