@Test
public void testCertificateRotation() throws Exception {
    // save the certificate on dn
    certCodec.writeCertificate(certHolder);
    Duration gracePeriod = securityConfig.getRenewalGracePeriod();
    X509CertificateHolder newCertHolder = generateX509CertHolder(null, LocalDateTime.now().plus(gracePeriod), Duration.ofSeconds(CERT_LIFETIME));
    String pemCert = CertificateCodec.getPEMEncodedString(newCertHolder);
    SCMSecurityProtocolProtos.SCMGetCertResponseProto responseProto = SCMSecurityProtocolProtos.SCMGetCertResponseProto.newBuilder().setResponseCode(SCMSecurityProtocolProtos.SCMGetCertResponseProto.ResponseCode.success).setX509Certificate(pemCert).setX509CACertificate(pemCert).setX509RootCACertificate(pemCert).build();
    when(scmClient.getDataNodeCertificateChain(anyObject(), anyString())).thenReturn(responseProto);
    List<String> rootCaList = new ArrayList<>();
    rootCaList.add(pemCert);
    when(scmClient.getAllRootCaCertificates()).thenReturn(rootCaList);
    // check that new cert ID should not equal to current cert ID
    String certId = newCertHolder.getSerialNumber().toString();
    Assert.assertFalse(certId.equals(client.getCertificate().getSerialNumber().toString()));
    // start monitor task to renew key and cert
    client.startCertificateRenewerService();
    // check after renew, client will have the new cert ID
    GenericTestUtils.waitFor(() -> {
        String newCertId = client.getCertificate().getSerialNumber().toString();
        return newCertId.equals(certId);
    }, 1000, CERT_LIFETIME * 1000);
    PrivateKey privateKey1 = client.getPrivateKey();
    PublicKey publicKey1 = client.getPublicKey();
    String caCertId1 = client.getCACertificate().getSerialNumber().toString();
    String rootCaCertId1 = client.getRootCACertificate().getSerialNumber().toString();
    // test the second time certificate rotation, generate a new cert
    newCertHolder = generateX509CertHolder(null, null, Duration.ofSeconds(CERT_LIFETIME));
    rootCaList.remove(pemCert);
    pemCert = CertificateCodec.getPEMEncodedString(newCertHolder);
    responseProto = SCMSecurityProtocolProtos.SCMGetCertResponseProto.newBuilder().setResponseCode(SCMSecurityProtocolProtos.SCMGetCertResponseProto.ResponseCode.success).setX509Certificate(pemCert).setX509CACertificate(pemCert).setX509RootCACertificate(pemCert).build();
    when(scmClient.getDataNodeCertificateChain(anyObject(), anyString())).thenReturn(responseProto);
    rootCaList.add(pemCert);
    when(scmClient.getAllRootCaCertificates()).thenReturn(rootCaList);
    String certId2 = newCertHolder.getSerialNumber().toString();
    // check after renew, client will have the new cert ID
    GenericTestUtils.waitFor(() -> {
        String newCertId = client.getCertificate().getSerialNumber().toString();
        return newCertId.equals(certId2);
    }, 1000, CERT_LIFETIME * 1000);
    Assert.assertFalse(client.getPrivateKey().equals(privateKey1));
    Assert.assertFalse(client.getPublicKey().equals(publicKey1));
    Assert.assertFalse(client.getCACertificate().getSerialNumber().toString().equals(caCertId1));
    Assert.assertFalse(client.getRootCACertificate().getSerialNumber().toString().equals(rootCaCertId1));
}

