@Test
public void testForEachRemaining() throws Exception {
    when(rocksIteratorMock.isValid()).thenReturn(true, true, true, true, true, true, true, false);
    when(rocksIteratorMock.key(any())).then(newAnswerInt("key1", 0x00)).then(newAnswerInt("key2", 0x00)).then(newAnswerInt("key3", 0x01)).then(newAnswerInt("key4", 0x02)).thenThrow(new NoSuchElementException());
    when(rocksIteratorMock.value(any())).then(newAnswerInt("val1", 0x7f)).then(newAnswerInt("val2", 0x7f)).then(newAnswerInt("val3", 0x7e)).then(newAnswerInt("val4", 0x7d)).thenThrow(new NoSuchElementException());
    List<Table.KeyValue<byte[], byte[]>> remaining = new ArrayList<>();
    try (RDBStoreCodecBufferIterator i = newIterator()) {
        i.forEachRemaining(kv -> {
            try {
                remaining.add(RawKeyValue.create(kv.getKey().getArray(), kv.getValue().getArray()));
            } catch (IOException e) {
                throw new RuntimeException(e);
            }
        });
        System.out.println("remaining: " + remaining);
        assertArrayEquals(new byte[] { 0x00 }, remaining.get(0).getKey());
        assertArrayEquals(new byte[] { 0x7f }, remaining.get(0).getValue());
        assertArrayEquals(new byte[] { 0x01 }, remaining.get(1).getKey());
        assertArrayEquals(new byte[] { 0x7e }, remaining.get(1).getValue());
        assertArrayEquals(new byte[] { 0x02 }, remaining.get(2).getKey());
        assertArrayEquals(new byte[] { 0x7d }, remaining.get(2).getValue());
    }
    CodecTestUtil.gc();
}

