private void setupContainerManager() throws IOException {
    dnList.add(DatanodeDetails.newBuilder().setUuid(UUID.randomUUID()).build());
    dnList.add(DatanodeDetails.newBuilder().setUuid(UUID.randomUUID()).build());
    dnList.add(DatanodeDetails.newBuilder().setUuid(UUID.randomUUID()).build());
    when(containerManager.getContainerReplicas(anyObject())).thenAnswer(invocationOnMock -> {
        ContainerID cid = (ContainerID) invocationOnMock.getArguments()[0];
        return replicas.get(cid.getId());
    });
    when(containerManager.getContainer(anyObject())).thenAnswer(invocationOnMock -> {
        ContainerID cid = (ContainerID) invocationOnMock.getArguments()[0];
        return containerTable.get(cid);
    });
    when(containerManager.getContainers()).thenReturn(new ArrayList<>(containers.values()));
    doAnswer(invocationOnMock -> {
        Map<ContainerID, Long> map = (Map<ContainerID, Long>) invocationOnMock.getArguments()[0];
        for (Map.Entry<ContainerID, Long> e : map.entrySet()) {
            ContainerInfo info = containers.get(e.getKey().getId());
            try {
                Assertions.assertTrue(e.getValue() > info.getDeleteTransactionId());
            } catch (AssertionError err) {
                throw new Exception("New TxnId " + e.getValue() + " < " + info.getDeleteTransactionId());
            }
            info.updateDeleteTransactionId(e.getValue());
            scmHADBTransactionBuffer.addToBuffer(containerTable, e.getKey(), info);
        }
        return null;
    }).when(containerManager).updateDeleteTransactionId(anyObject());
}

