    When StatefulServiceStateManager#saveConfiguration is called, save to
    in-memory serviceToConfigMap instead.
     */
    Mockito.doAnswer(i -> {
        serviceToConfigMap.put(i.getArgument(0, String.class), i.getArgument(1, ByteString.class));
        return null;
    }).when(serviceStateManager).saveConfiguration(Mockito.any(String.class), Mockito.any(ByteString.class));
    /*
    When StatefulServiceStateManager#readConfiguration is called, read from
    serviceToConfigMap instead.
     */
    when(serviceStateManager.readConfiguration(Mockito.anyString())).thenAnswer(i -> serviceToConfigMap.get(i.getArgument(0, String.class)));
    Mockito.doNothing().when(scmServiceManager).register(Mockito.any(SCMService.class));
