public void checkIterationResultTimeoutFromReplicationManager() throws NodeNotFoundException, IOException, IllegalContainerBalancerStateException, InvalidContainerBalancerConfigurationException, TimeoutException {
    CompletableFuture<MoveManager.MoveResult> future = CompletableFuture.supplyAsync(() -> MoveManager.MoveResult.REPLICATION_FAIL_TIME_OUT);
    CompletableFuture<MoveManager.MoveResult> future2 = CompletableFuture.supplyAsync(() -> MoveManager.MoveResult.DELETION_FAIL_TIME_OUT);
    Mockito.when(replicationManager.move(Mockito.any(ContainerID.class), Mockito.any(DatanodeDetails.class), Mockito.any(DatanodeDetails.class))).thenReturn(future, future2);
    balancerConfiguration.setThreshold(10);
    balancerConfiguration.setIterations(1);
    balancerConfiguration.setMaxSizeEnteringTarget(10 * STORAGE_UNIT);
    balancerConfiguration.setMaxSizeToMovePerIteration(100 * STORAGE_UNIT);
    balancerConfiguration.setMaxDatanodesPercentageToInvolvePerIteration(100);
    balancerConfiguration.setMoveTimeout(Duration.ofMillis(500));
    rmConf.setEnableLegacy(true);
    startBalancer(balancerConfiguration);
    Assertions.assertTrue(containerBalancerTask.getMetrics().getNumContainerMovesTimeoutInLatestIteration() > 0);
    Assertions.assertEquals(0, containerBalancerTask.getMetrics().getNumContainerMovesCompletedInLatestIteration());
    stopBalancer();
    /*
    Try the same test with MoveManager instead of LegacyReplicationManager.
     */
    Mockito.when(moveManager.move(Mockito.any(ContainerID.class), Mockito.any(DatanodeDetails.class), Mockito.any(DatanodeDetails.class))).thenReturn(future).thenAnswer(invocation -> future2);
    rmConf.setEnableLegacy(false);
    startBalancer(balancerConfiguration);
    Assertions.assertTrue(containerBalancerTask.getMetrics().getNumContainerMovesTimeoutInLatestIteration() > 0);
    Assertions.assertEquals(0, containerBalancerTask.getMetrics().getNumContainerMovesCompletedInLatestIteration());
    stopBalancer();
}

