@Test
public void selectedContainerShouldNotAlreadyHaveBeenSelected() throws IllegalContainerBalancerStateException, IOException, InvalidContainerBalancerConfigurationException, NodeNotFoundException, TimeoutException {
    balancerConfiguration.setThreshold(10);
    balancerConfiguration.setMaxDatanodesPercentageToInvolvePerIteration(100);
    balancerConfiguration.setMaxSizeToMovePerIteration(50 * STORAGE_UNIT);
    balancerConfiguration.setMaxSizeEnteringTarget(50 * STORAGE_UNIT);
    balancerConfiguration.setIterations(1);
    rmConf.setEnableLegacy(true);
    startBalancer(balancerConfiguration);
    stopBalancer();
    int numContainers = containerBalancerTask.getContainerToTargetMap().size();
    /*
    Assuming move is called exactly once for each unique container, number of
     calls to move should equal number of unique containers. If number of
     calls to move is more than number of unique containers, at least one
     container has been re-selected. It's expected that number of calls to
     move should equal number of unique, selected containers (from
     containerToTargetMap).
     */
    Mockito.verify(replicationManager, times(numContainers)).move(any(ContainerID.class), any(DatanodeDetails.class), any(DatanodeDetails.class));
    /*
     Try the same test by disabling LegacyReplicationManager so that
     MoveManager is used.
     */
    rmConf.setEnableLegacy(false);
    startBalancer(balancerConfiguration);
    stopBalancer();
    numContainers = containerBalancerTask.getContainerToTargetMap().size();
    Mockito.verify(moveManager, times(numContainers)).move(any(ContainerID.class), any(DatanodeDetails.class), any(DatanodeDetails.class));
}

@Test
public void testMetrics() throws IllegalContainerBalancerStateException, IOException, InvalidContainerBalancerConfigurationException, TimeoutException, NodeNotFoundException {
    conf.set("hdds.datanode.du.refresh.period", "1ms");
    balancerConfiguration.setBalancingInterval(Duration.ofMillis(2));
    balancerConfiguration.setThreshold(10);
    balancerConfiguration.setIterations(1);
    balancerConfiguration.setMaxSizeEnteringTarget(6 * STORAGE_UNIT);
    // deliberately set max size per iteration to a low value, 6 GB
    balancerConfiguration.setMaxSizeToMovePerIteration(6 * STORAGE_UNIT);
    balancerConfiguration.setMaxDatanodesPercentageToInvolvePerIteration(100);
    Mockito.when(moveManager.move(any(), any(), any())).thenReturn(CompletableFuture.completedFuture(MoveManager.MoveResult.REPLICATION_FAIL_NODE_UNHEALTHY)).thenReturn(CompletableFuture.completedFuture(MoveManager.MoveResult.COMPLETED));
    startBalancer(balancerConfiguration);
    stopBalancer();
    ContainerBalancerMetrics metrics = containerBalancerTask.getMetrics();
    Assertions.assertEquals(determineExpectedUnBalancedNodes(balancerConfiguration.getThreshold()).size(), metrics.getNumDatanodesUnbalanced());
    Assertions.assertTrue(metrics.getDataSizeMovedGBInLatestIteration() <= 6);
    Assertions.assertTrue(metrics.getDataSizeMovedGB() > 0);
    Assertions.assertEquals(1, metrics.getNumIterations());
    Assertions.assertTrue(metrics.getNumContainerMovesScheduledInLatestIteration() > 0);
    Assertions.assertEquals(metrics.getNumContainerMovesScheduled(), metrics.getNumContainerMovesScheduledInLatestIteration());
    Assertions.assertEquals(metrics.getNumContainerMovesScheduled(), metrics.getNumContainerMovesCompleted() + metrics.getNumContainerMovesFailed() + metrics.getNumContainerMovesTimeout());
    Assertions.assertEquals(0, metrics.getNumContainerMovesTimeout());
    Assertions.assertEquals(1, metrics.getNumContainerMovesFailed());
}

/**
 * Tests the situation where some container moves time out because they
 * take longer than "move.timeout".
 */
@Test
public void checkIterationResultTimeout() throws NodeNotFoundException, IOException, IllegalContainerBalancerStateException, InvalidContainerBalancerConfigurationException, TimeoutException {
    CompletableFuture<MoveManager.MoveResult> completedFuture = CompletableFuture.completedFuture(MoveManager.MoveResult.COMPLETED);
    Mockito.when(replicationManager.move(Mockito.any(ContainerID.class), Mockito.any(DatanodeDetails.class), Mockito.any(DatanodeDetails.class))).thenReturn(completedFuture).thenAnswer(invocation -> genCompletableFuture(2000));
    balancerConfiguration.setThreshold(10);
    balancerConfiguration.setIterations(1);
    balancerConfiguration.setMaxSizeEnteringTarget(10 * STORAGE_UNIT);
    balancerConfiguration.setMaxSizeToMovePerIteration(100 * STORAGE_UNIT);
    balancerConfiguration.setMaxDatanodesPercentageToInvolvePerIteration(100);
    balancerConfiguration.setMoveTimeout(Duration.ofMillis(500));
    rmConf.setEnableLegacy(true);
    startBalancer(balancerConfiguration);
    /*
    According to the setup and configurations, this iteration's result should
    be ITERATION_COMPLETED.
     */
    Assertions.assertEquals(ContainerBalancerTask.IterationResult.ITERATION_COMPLETED, containerBalancerTask.getIterationResult());
    Assertions.assertEquals(1, containerBalancerTask.getMetrics().getNumContainerMovesCompletedInLatestIteration());
    Assertions.assertTrue(containerBalancerTask.getMetrics().getNumContainerMovesTimeoutInLatestIteration() > 1);
    stopBalancer();
    /*
    Test the same but use MoveManager instead of LegacyReplicationManager.
    The first move being 10ms falls within the timeout duration of 500ms. It
    should be successful. The rest should fail.
     */
    rmConf.setEnableLegacy(false);
    Mockito.when(moveManager.move(Mockito.any(ContainerID.class), Mockito.any(DatanodeDetails.class), Mockito.any(DatanodeDetails.class))).thenReturn(completedFuture).thenAnswer(invocation -> genCompletableFuture(2000));
    startBalancer(balancerConfiguration);
    Assertions.assertEquals(ContainerBalancerTask.IterationResult.ITERATION_COMPLETED, containerBalancerTask.getIterationResult());
    Assertions.assertEquals(1, containerBalancerTask.getMetrics().getNumContainerMovesCompletedInLatestIteration());
    Assertions.assertTrue(containerBalancerTask.getMetrics().getNumContainerMovesTimeoutInLatestIteration() > 1);
    stopBalancer();
}

