@Test
public void testEmptyContainerInClosingState() throws InterruptedException {
    /*
     * Empty Container in CLOSING state should be CLOSED after
     * a timeout (ReplicationManager Interval * 5)
     */
    Duration replicationInterval = Duration.ofSeconds(1);
    rmConf.setInterval(replicationInterval);
    ContainerInfo containerInfo = TestContainerInfo.newBuilderForTest().setReplicationConfig(RATIS_REPLICATION_CONFIG).setContainerID(1).setState(CLOSING).setClock(clock).build();
    ContainerCheckRequest request = new ContainerCheckRequest.Builder().setPendingOps(Collections.emptyList()).setReport(new ReplicationManagerReport()).setContainerInfo(containerInfo).setContainerReplicas(new HashSet<>()).build();
    // not enough time has elapsed
    Duration notEnoughTime = replicationInterval.multipliedBy(3).plusMillis(1);
    clock.fastForward(notEnoughTime);
    assertAndVerify(request, true, 0);
    Mockito.verify(replicationManager, never()).updateContainerState(containerInfo.containerID(), CLOSE);
    // wait time has elapsed (3x + 2x + a bit)
    Duration moreTime = replicationInterval.multipliedBy(2);
    clock.fastForward(moreTime);
    assertAndVerify(request, true, 0);
    Mockito.verify(replicationManager, Mockito.times(1)).updateContainerState(containerInfo.containerID(), CLOSE);
}

