public void testClosingRatisWithUnhealthyReplicas() {
    ContainerInfo containerInfo = ReplicationTestUtil.createContainerInfo(RATIS_REPLICATION_CONFIG, 1, CLOSING);
    Set<ContainerReplica> containerReplicas = ReplicationTestUtil.createReplicas(containerInfo.containerID(), ContainerReplicaProto.State.UNHEALTHY, 0, 0, 0);
