    ContainerInfo container = createContainerInfo(repConfig);
    Mockito.when(placementPolicy.validateContainerPlacement(Mockito.any(), Mockito.anyInt())).thenAnswer(invocation -> {
        List<DatanodeDetails> dns = invocation.getArgument(0);
