    ContainerReplica unhealthyReplica = createContainerReplica(container.containerID(), 1, IN_SERVICE, State.UNHEALTHY);
    replicas.add(unhealthyReplica);
    List<ContainerReplicaOp> pending = new ArrayList<>();
    pending.add(ContainerReplicaOp.create(DELETE, unhealthyReplica.getDatanodeDetails(), 1));
    ContainerCheckRequest request = requestBuilder.setContainerReplicas(replicas).setContainerInfo(container).setPendingOps(pending).build();
    ContainerHealthResult result = handler.checkMisReplication(request);
