/**
 * Scenario: Container is both over replicated and mis replicated.
 * Expectation: It should be queued for over replication.
 */
@Test
public void testOverReplicatedWithMisReplication() {
    Mockito.when(containerPlacementPolicy.validateContainerPlacement(Mockito.any(), Mockito.anyInt())).thenAnswer(invocation -> new ContainerPlacementStatusDefault(1, 2, 3));
    ContainerInfo container = createContainerInfo(repConfig);
    Set<ContainerReplica> replicas = createReplicas(container.containerID(), State.CLOSED, 0, 0, 0);
    Set<ContainerReplica> unhealthyReplicas = createReplicas(container.containerID(), State.UNHEALTHY, 0, 0, 0);
    replicas.addAll(unhealthyReplicas);
    requestBuilder.setContainerReplicas(replicas).setContainerInfo(container);
    ContainerHealthResult result = healthCheck.checkHealth(requestBuilder.build());
    // there's an excess of 3 UNHEALTHY replicas, so it's over replicated
    assertEquals(HealthState.OVER_REPLICATED, result.getHealthState());
    OverReplicatedHealthResult overRepResult = (OverReplicatedHealthResult) result;
    assertEquals(3, overRepResult.getExcessRedundancy());
    assertFalse(overRepResult.hasMismatchedReplicas());
    assertFalse(overRepResult.isReplicatedOkAfterPending());
    assertTrue(healthCheck.handle(requestBuilder.build()));
    assertEquals(0, repQueue.underReplicatedQueueSize());
    assertEquals(1, repQueue.overReplicatedQueueSize());
    assertEquals(1, report.getStat(ReplicationManagerReport.HealthState.OVER_REPLICATED));
    assertEquals(0, report.getStat(ReplicationManagerReport.HealthState.UNDER_REPLICATED));
    assertEquals(0, report.getStat(ReplicationManagerReport.HealthState.MIS_REPLICATED));
}

