/**
 * HDDS-7683 was a case where the maintenance logic was calling the placement
 * policy requesting zero nodes. This test asserts that it is never called
 * with zero nodes to ensure that issue is fixed.
 */
@Test
public void testMaintenanceDoesNotRequestZeroNodes() throws IOException {
    Set<ContainerReplica> availableReplicas = ReplicationTestUtil.createReplicas(Pair.of(DECOMMISSIONING, 1), Pair.of(IN_SERVICE, 2), Pair.of(IN_MAINTENANCE, 3), Pair.of(IN_SERVICE, 4), Pair.of(IN_SERVICE, 5));
    when(ecPlacementPolicy.chooseDatanodes(anyList(), anyList(), isNull(), anyInt(), anyLong(), anyLong())).thenAnswer(invocationOnMock -> {
        int numNodes = invocationOnMock.getArgument(3);
        List<DatanodeDetails> targets = new ArrayList<>();
        for (int i = 0; i < numNodes; i++) {
            targets.add(MockDatanodeDetails.randomDatanodeDetails());
        }
        return targets;
    });
    UnderReplicatedHealthResult result = mock(UnderReplicatedHealthResult.class);
    when(result.getContainerInfo()).thenReturn(container);
    ECUnderReplicationHandler handler = new ECUnderReplicationHandler(ecPlacementPolicy, conf, replicationManager);
    handler.processAndSendCommands(availableReplicas, emptyList(), result, 1);
    assertEquals(1, commandsSent.size());
    verify(ecPlacementPolicy, times(0)).chooseDatanodes(anyList(), isNull(), eq(0), anyLong(), anyLong());
}

