@Test
public void testUnderRepDueToDecomAndOverRep() throws IOException {
    PlacementPolicy sameNodePolicy = ReplicationTestUtil.getNoNodesTestPlacementPolicy(nodeManager, conf);
    // First it is under-replicated, due to decom index 5, but no mode will be
    // found. This will cause an exception to be thrown out, as the container is
    // not also over replicated.
    Set<ContainerReplica> availableReplicas = ReplicationTestUtil.createReplicas(Pair.of(IN_SERVICE, 1), Pair.of(IN_SERVICE, 2), Pair.of(IN_SERVICE, 3), Pair.of(IN_SERVICE, 4), Pair.of(DECOMMISSIONING, 5));
    ECUnderReplicationHandler ecURH = new ECUnderReplicationHandler(sameNodePolicy, conf, replicationManager);
    UnderReplicatedHealthResult underRep = new UnderReplicatedHealthResult(container, 1, true, false, false);
    assertThrows(SCMException.class, () -> ecURH.processAndSendCommands(availableReplicas, emptyList(), underRep, 1));
    // Now adjust replicas so it is also over replicated. This time it should
    // call the OverRepHandler and then throw
    ContainerReplica overRepReplica = createContainerReplica(container.containerID(), 4, IN_SERVICE, CLOSED);
    availableReplicas.add(overRepReplica);
    Set<Pair<DatanodeDetails, SCMCommand<?>>> expectedDelete = new HashSet<>();
    expectedDelete.add(Pair.of(overRepReplica.getDatanodeDetails(), createDeleteContainerCommand(container, overRepReplica.getReplicaIndex())));
    when(replicationManager.processOverReplicatedContainer(underRep)).thenAnswer(invocationOnMock -> {
        commandsSent.addAll(expectedDelete);
        return expectedDelete.size();
    });
    assertThrows(SCMException.class, () -> ecURH.processAndSendCommands(availableReplicas, emptyList(), underRep, 1));
    verify(replicationManager, times(1)).processOverReplicatedContainer(underRep);
    assertEquals(expectedDelete, commandsSent);
}

