/**
 * In small clusters, handling an under replicated container can get
 * blocked because DNs are occupied by unhealthy replicas. This
 * would make the placement policy throw an exception because it could
 * not find any target datanodes for new replicas.
 *
 * Situation:
 * Consider a CLOSED container with replicas 1 CLOSED, 1 QUASI_CLOSED with
 * same seq id as the container, and 1 QUASI_CLOSED with smaller seq id.
 * Placement policy is mocked to simulate no other target DNs are available.
 *
 * Expectation:
 * 1st iteration: QUASI_CLOSED with same seq id should get closed, and the
 * one with smaller seq id should get deleted to free up a DN.
 * 2nd iteration: Any CLOSED replica should be replicated.
 * 3rd iteration: Container should be OK now.
 */
@Test
public void testUnderReplicationBlockedByUnhealthyReplicas() throws IOException, TimeoutException {
    /*
      In the first iteration, throw an SCMException to simulate that placement
      policy could not find any targets. In the second iteration, return a list
      of required targets.
       */
    Mockito.when(ratisContainerPlacementPolicy.chooseDatanodes(Mockito.any(), Mockito.any(), Mockito.anyInt(), Mockito.anyLong(), Mockito.anyLong())).thenAnswer(invocation -> {
        throw new SCMException(SCMException.ResultCodes.FAILED_TO_FIND_SUITABLE_NODE);
    }).thenAnswer(invocation -> {
        int nodesRequired = invocation.getArgument(2);
        List<DatanodeDetails> nodes = new ArrayList<>(nodesRequired);
        while (nodesRequired != 0) {
            nodes.add(MockDatanodeDetails.randomDatanodeDetails());
            nodesRequired--;
        }
        return nodes;
    });
    final ContainerInfo container = createContainer(LifeCycleState.CLOSED);
    addReplicaToDn(container, randomDatanodeDetails(), CLOSED, container.getSequenceId());
    ContainerReplica quasiToDelete = addReplicaToDn(container, randomDatanodeDetails(), QUASI_CLOSED, container.getSequenceId() - 1);
    ContainerReplica quasi2 = addReplicaToDn(container, randomDatanodeDetails(), QUASI_CLOSED, container.getSequenceId());
    // First RM iteration.
    // this container is under replicated by 2 replicas.
    // quasi2 should be closed since its BCSID matches the container's.
    // delete command should be sent for quasiToDelete to unblock under rep
    // handling.
    assertDeleteScheduled(1);
    Assertions.assertTrue(datanodeCommandHandler.received(SCMCommandProto.Type.closeContainerCommand, quasi2.getDatanodeDetails()));
    Assertions.assertTrue(datanodeCommandHandler.received(SCMCommandProto.Type.deleteContainerCommand, quasiToDelete.getDatanodeDetails()));
    assertUnderReplicatedCount(1);
    // Update RM with the results of the close and delete commands
    ContainerReplica quasiToClosed = getReplicaBuilder(container.containerID(), CLOSED, quasi2.getBytesUsed(), quasi2.getKeyCount(), container.getSequenceId(), quasi2.getOriginDatanodeId(), quasi2.getDatanodeDetails()).build();
    containerStateManager.updateContainerReplica(container.containerID(), quasiToClosed);
    containerStateManager.removeContainerReplica(container.containerID(), quasiToDelete);
    // Second RM iteration
    // Now that we have a free DN, a closed replica should be replicated
    assertReplicaScheduled(1);
    assertUnderReplicatedCount(1);
    // Process the replicate command and report the replica back to SCM.
    List<CommandForDatanode> replicateCommands = datanodeCommandHandler.getReceivedCommands().stream().filter(c -> c.getCommand().getType().equals(SCMCommandProto.Type.replicateContainerCommand)).collect(Collectors.toList());
    Assertions.assertEquals(1, replicateCommands.size());
    // Report the new replica to SCM.
    for (CommandForDatanode replicateCommand : replicateCommands) {
        DatanodeDetails newNode = createDatanodeDetails(replicateCommand.getDatanodeId());
