    Set<DatanodeDetails> remainingReplicasAfterCopy = availableReplicas.stream().filter(r -> !copy.contains(r)).map(ContainerReplica::getDatanodeDetails).collect(Collectors.toSet());
    List<DatanodeDetails> targetNodes = IntStream.range(0, expectedNumberOfNodes).mapToObj(i -> MockDatanodeDetails.randomDatanodeDetails()).collect(Collectors.toList());
    if (expectedNumberOfNodes > 0) {
        Mockito.when(mockedPlacementPolicy.chooseDatanodes(any(), any(), any(), eq(copy.size()), Mockito.anyLong(), Mockito.anyLong())).thenAnswer(invocation -> {
            List<DatanodeDetails> datanodeDetails = invocation.getArgument(0);
            Assertions.assertTrue(remainingReplicasAfterCopy.containsAll(datanodeDetails));
            return targetNodes;
        });
    }
    Map<DatanodeDetails, Integer> replicaIndexMap = copy.stream().collect(Collectors.toMap(ContainerReplica::getDatanodeDetails, ContainerReplica::getReplicaIndex));
    try {
        misReplicationHandler.processAndSendCommands(availableReplicas, pendingOp, result, maintenanceCnt);
    } finally {
        Assertions.assertEquals(expectedNumberOfCommands, commandsSent.size());
        for (Pair<DatanodeDetails, SCMCommand<?>> pair : commandsSent) {
            SCMCommand<?> command = pair.getValue();
            Assertions.assertSame(replicateContainerCommand, command.getType());
            ReplicateContainerCommand replicateContainerCommand = (ReplicateContainerCommand) command;
            Assertions.assertEquals(replicateContainerCommand.getContainerID(), container.getContainerID());
            DatanodeDetails replicateSrcDn = pair.getKey();
            DatanodeDetails target = replicateContainerCommand.getTargetDatanode();
            Assertions.assertTrue(sourceDns.contains(replicateSrcDn));
            Assertions.assertTrue(targetNodes.contains(target));
            int replicaIndex = replicateContainerCommand.getReplicaIndex();
            assertReplicaIndex(replicaIndexMap, replicateSrcDn, replicaIndex);
        }
    }
}

