public void testCorrectUsedAndExcludedNodesPassed() throws IOException {
    PlacementPolicy mockPolicy = Mockito.mock(PlacementPolicy.class);
    Mockito.when(mockPolicy.chooseDatanodes(any(), any(), any(), anyInt(), anyLong(), anyLong())).thenReturn(Collections.singletonList(MockDatanodeDetails.randomDatanodeDetails()));
    ArgumentCaptor<List<DatanodeDetails>> usedNodesCaptor = ArgumentCaptor.forClass(List.class);
    ArgumentCaptor<List<DatanodeDetails>> excludedNodesCaptor = ArgumentCaptor.forClass(List.class);
    RatisUnderReplicationHandler handler = new RatisUnderReplicationHandler(mockPolicy, conf, replicationManager);
    Set<ContainerReplica> replicas = new HashSet<>();
    ContainerReplica good = createContainerReplica(container.containerID(), 0, IN_SERVICE, State.CLOSED, 1);
    replicas.add(good);
    ContainerReplica unhealthy = createContainerReplica(container.containerID(), 0, IN_SERVICE, State.UNHEALTHY, 1);
    replicas.add(unhealthy);
    ContainerReplica decommissioning = createContainerReplica(container.containerID(), 0, DECOMMISSIONING, State.CLOSED, 1);
    replicas.add(decommissioning);
    ContainerReplica maintenance = createContainerReplica(container.containerID(), 0, IN_MAINTENANCE, State.CLOSED, 1);
    replicas.add(maintenance);
    List<ContainerReplicaOp> pendingOps = new ArrayList<>();
    DatanodeDetails pendingAdd = MockDatanodeDetails.randomDatanodeDetails();
    DatanodeDetails pendingRemove = MockDatanodeDetails.randomDatanodeDetails();
    pendingOps.add(ContainerReplicaOp.create(ContainerReplicaOp.PendingOpType.ADD, pendingAdd, 0));
    pendingOps.add(ContainerReplicaOp.create(ContainerReplicaOp.PendingOpType.DELETE, pendingRemove, 0));
    handler.processAndSendCommands(replicas, pendingOps, getUnderReplicatedHealthResult(), 2);
    Mockito.verify(mockPolicy, times(1)).chooseDatanodes(usedNodesCaptor.capture(), excludedNodesCaptor.capture(), any(), anyInt(), anyLong(), anyLong());
    List<DatanodeDetails> usedNodes = usedNodesCaptor.getValue();
    List<DatanodeDetails> excludedNodes = excludedNodesCaptor.getValue();
    Assertions.assertTrue(usedNodes.contains(good.getDatanodeDetails()));
    Assertions.assertTrue(usedNodes.contains(maintenance.getDatanodeDetails()));
    Assertions.assertTrue(usedNodes.contains(pendingAdd));
    Assertions.assertTrue(excludedNodes.contains(unhealthy.getDatanodeDetails()));
    Assertions.assertTrue(excludedNodes.contains(decommissioning.getDatanodeDetails()));
    Assertions.assertTrue(excludedNodes.contains(pendingRemove));
}

