@Test
public void testMessageNotProcessedIfGlobalLimitReached() throws IOException {
    AtomicLong inFlightReplications = new AtomicLong(11);
    Mockito.when(replicationManager.getReplicationInFlightLimit()).thenReturn(10L);
    Mockito.doAnswer(invocation -> inFlightReplications.get()).when(replicationManager).getInflightReplicationCount();
    Mockito.when(replicationManager.processUnderReplicatedContainer(any())).thenReturn(1);
    ContainerInfo container = ReplicationTestUtil.createContainer(HddsProtos.LifeCycleState.CLOSED, repConfig);
    UnderReplicatedHealthResult result = new UnderReplicatedHealthResult(container, 3, false, false, false);
    queue.enqueue(result);
    underReplicatedProcessor.processAll(queue);
    // The message should not be processed and still be on the queue (re-queued)
    assertEquals(1, queue.underReplicatedQueueSize());
    // We should not have processed anything in RM
    Mockito.verify(replicationManager, Mockito.times(0)).processUnderReplicatedContainer(any());
    // Change the inflight replications to a value below the limit
    inFlightReplications.set(8);
    underReplicatedProcessor.processAll(queue);
    assertEquals(0, queue.underReplicatedQueueSize());
    // We should have processed the message now
    Mockito.verify(replicationManager, Mockito.times(1)).processUnderReplicatedContainer(any());
    assertEquals(1, rmMetrics.getPendingReplicationLimitReachedTotal());
}

