@Test
public void testCloseContainerWithDelayByLeaseManager() throws Exception {
    final Pipeline pipeline = createPipeline(RATIS_REP_CONFIG, 3);
    final ContainerInfo container = createContainer(RATIS_REP_CONFIG, pipeline.getId());
    container.setState(HddsProtos.LifeCycleState.CLOSING);
    Mockito.when(containerManager.getContainer(container.containerID())).thenReturn(container);
    SCMContext scmContext = Mockito.mock(SCMContext.class);
    Mockito.when(scmContext.isLeader()).thenReturn(true);
    long timeoutInMs = 2000;
    Mockito.when(pipelineManager.getPipeline(pipeline.getId())).thenReturn(pipeline);
    LeaseManager<Object> leaseManager = new LeaseManager<>("test", timeoutInMs);
    leaseManager.start();
    LeaseManager mockLeaseManager = Mockito.mock(LeaseManager.class);
    List<Lease<Object>> leaseList = new ArrayList<>(1);
    Mockito.when(mockLeaseManager.acquire(any(), anyLong(), any())).thenAnswer(invocation -> {
        leaseList.add(leaseManager.acquire(invocation.getArgument(0, Object.class), invocation.getArgument(1), invocation.getArgument(2, Callable.class)));
        return leaseList.get(0);
    });
    CloseContainerEventHandler closeHandler = new CloseContainerEventHandler(pipelineManager, containerManager, scmContext, mockLeaseManager, timeoutInMs);
    closeHandler.onMessage(container.containerID(), eventPublisher);
    Mockito.verify(mockLeaseManager, atLeastOnce()).acquire(any(), anyLong(), any());
    Assert.assertTrue(leaseList.size() > 0);
    // immediate check if event is published
    Mockito.verify(eventPublisher, never()).fireEvent(eq(DATANODE_COMMAND), commandCaptor.capture());
    // wait for event to happen
    GenericTestUtils.waitFor(() -> {
        try {
            Mockito.verify(eventPublisher, atLeastOnce()).fireEvent(eq(DATANODE_COMMAND), commandCaptor.capture());
        } catch (Throwable ex) {
            return false;
        }
        return true;
    }, 1000, (int) timeoutInMs * 3);
    leaseManager.shutdown();
}

