@Test
public void testClosingToClosed() throws NodeNotFoundException, IOException, TimeoutException {
    /*
     * The container is in CLOSING state and all the replicas are in
     * OPEN/CLOSING state.
     *
     * The datanode reports that one of the replica is now CLOSED.
     *
     * In this case SCM should mark the container as CLOSED.
     */
    final ContainerReportHandler reportHandler = new ContainerReportHandler(nodeManager, containerManager);
    final Iterator<DatanodeDetails> nodeIterator = nodeManager.getNodes(NodeStatus.inServiceHealthy()).iterator();
    final DatanodeDetails datanodeOne = nodeIterator.next();
    final DatanodeDetails datanodeTwo = nodeIterator.next();
    final DatanodeDetails datanodeThree = nodeIterator.next();
    final ContainerInfo containerOne = getContainer(LifeCycleState.CLOSING);
    final ContainerInfo containerTwo = getContainer(LifeCycleState.CLOSED);
    final Set<ContainerID> containerIDSet = Stream.of(containerOne.containerID(), containerTwo.containerID()).collect(Collectors.toSet());
    final Set<ContainerReplica> containerOneReplicas = getReplicas(containerOne.containerID(), ContainerReplicaProto.State.CLOSING, datanodeOne);
    containerOneReplicas.addAll(getReplicas(containerOne.containerID(), ContainerReplicaProto.State.OPEN, datanodeTwo, datanodeThree));
    final Set<ContainerReplica> containerTwoReplicas = getReplicas(containerTwo.containerID(), ContainerReplicaProto.State.CLOSED, datanodeOne, datanodeTwo, datanodeThree);
    nodeManager.setContainers(datanodeOne, containerIDSet);
    nodeManager.setContainers(datanodeTwo, containerIDSet);
    nodeManager.setContainers(datanodeThree, containerIDSet);
    containerStateManager.addContainer(containerOne.getProtobuf());
    containerStateManager.addContainer(containerTwo.getProtobuf());
    containerOneReplicas.forEach(r -> containerStateManager.updateContainerReplica(containerTwo.containerID(), r));
    containerTwoReplicas.forEach(r -> containerStateManager.updateContainerReplica(containerTwo.containerID(), r));
    final ContainerReportsProto containerReport = getContainerReportsProto(containerOne.containerID(), ContainerReplicaProto.State.CLOSED, datanodeOne.getUuidString());
    final ContainerReportFromDatanode containerReportFromDatanode = new ContainerReportFromDatanode(datanodeOne, containerReport);
    reportHandler.onMessage(containerReportFromDatanode, publisher);
    Assertions.assertEquals(LifeCycleState.CLOSED, containerManager.getContainer(containerOne.containerID()).getState());
}

@Test
public void testClosingToClosedForECContainer() throws NodeNotFoundException, IOException, TimeoutException {
    // Create an EC 3-2 container
    ECReplicationConfig replicationConfig = new ECReplicationConfig(3, 2);
    final ContainerInfo container = getECContainer(LifeCycleState.CLOSING, PipelineID.randomId(), replicationConfig);
    List<DatanodeDetails> dns = setupECContainerForTesting(container);
    createAndHandleContainerReport(container.containerID(), ContainerReplicaProto.State.CLOSED, dns.get(1), 2);
    // index is 2; container shouldn't transition to CLOSED
    Assertions.assertEquals(LifeCycleState.CLOSING, containerManager.getContainer(container.containerID()).getState());
    createAndHandleContainerReport(container.containerID(), ContainerReplicaProto.State.CLOSED, dns.get(2), 3);
    // index is 3; container shouldn't transition to CLOSED
    Assertions.assertEquals(LifeCycleState.CLOSING, containerManager.getContainer(container.containerID()).getState());
    createAndHandleContainerReport(container.containerID(), ContainerReplicaProto.State.CLOSED, dns.get(0), 1);
    // index is 1; container should transition to CLOSED
    Assertions.assertEquals(LifeCycleState.CLOSED, containerManager.getContainer(container.containerID()).getState());
    // Test with an EC 6-3 container
    replicationConfig = new ECReplicationConfig(6, 3);
    final ContainerInfo container2 = getECContainer(LifeCycleState.CLOSING, PipelineID.randomId(), replicationConfig);
    dns = setupECContainerForTesting(container2);
    createAndHandleContainerReport(container2.containerID(), ContainerReplicaProto.State.CLOSED, dns.get(5), 6);
    // index is 6, container shouldn't transition to CLOSED
    Assertions.assertEquals(LifeCycleState.CLOSING, containerManager.getContainer(container2.containerID()).getState());
    createAndHandleContainerReport(container2.containerID(), ContainerReplicaProto.State.CLOSED, dns.get(8), 9);
    // index is 9, container should transition to CLOSED
    Assertions.assertEquals(LifeCycleState.CLOSED, containerManager.getContainer(container2.containerID()).getState());
}

