@Test
public void testClosingToClosedForECContainer() throws NodeNotFoundException, IOException, TimeoutException {
    // Create an EC 3-2 container
    ECReplicationConfig replicationConfig = new ECReplicationConfig(3, 2);
    final ContainerInfo container = getECContainer(LifeCycleState.CLOSING, PipelineID.randomId(), replicationConfig);
    List<DatanodeDetails> dns = setupECContainerForTesting(container);
    createAndHandleICR(container.containerID(), ContainerReplicaProto.State.CLOSED, dns.get(1), 2);
    // index is 2; container shouldn't transition to CLOSED
    Assertions.assertEquals(LifeCycleState.CLOSING, containerManager.getContainer(container.containerID()).getState());
    createAndHandleICR(container.containerID(), ContainerReplicaProto.State.CLOSED, dns.get(2), 3);
    // index is 3; container shouldn't transition to CLOSED
    Assertions.assertEquals(LifeCycleState.CLOSING, containerManager.getContainer(container.containerID()).getState());
    createAndHandleICR(container.containerID(), ContainerReplicaProto.State.CLOSED, dns.get(0), 1);
    // index is 1; container should transition to CLOSED
    Assertions.assertEquals(LifeCycleState.CLOSED, containerManager.getContainer(container.containerID()).getState());
    // Test with an EC 6-3 container
    replicationConfig = new ECReplicationConfig(6, 3);
    final ContainerInfo container2 = getECContainer(LifeCycleState.CLOSING, PipelineID.randomId(), replicationConfig);
    dns = setupECContainerForTesting(container2);
    createAndHandleICR(container2.containerID(), ContainerReplicaProto.State.CLOSED, dns.get(5), 6);
    // index is 6, container shouldn't transition to CLOSED
    Assertions.assertEquals(LifeCycleState.CLOSING, containerManager.getContainer(container2.containerID()).getState());
    createAndHandleICR(container2.containerID(), ContainerReplicaProto.State.CLOSED, dns.get(8), 9);
    // index is 9, container should transition to CLOSED
    Assertions.assertEquals(LifeCycleState.CLOSED, containerManager.getContainer(container2.containerID()).getState());
}

