@Test
public void testDecommissionAbortedWhenNodeInUnexpectedState() throws NodeNotFoundException, ContainerNotFoundException {
    DatanodeDetails dn1 = MockDatanodeDetails.randomDatanodeDetails();
    nodeManager.register(dn1, new NodeStatus(HddsProtos.NodeOperationalState.DECOMMISSIONING, HddsProtos.NodeState.HEALTHY));
    nodeManager.setContainers(dn1, generateContainers(3));
    DatanodeAdminMonitorTestUtil.mockGetContainerReplicaCount(repManager, HddsProtos.LifeCycleState.CLOSED, DECOMMISSIONED, IN_SERVICE, IN_SERVICE);
    // Add the node to the monitor, it should have 3 under-replicated containers
    // after the first run
    monitor.startMonitoring(dn1);
    monitor.run();
    assertEquals(1, monitor.getTrackedNodeCount());
    DatanodeDetails node = getFirstTrackedNode();
    assertEquals(HddsProtos.NodeOperationalState.DECOMMISSIONING, nodeManager.getNodeStatus(dn1).getOperationalState());
    // Set the node to dead, and then the workflow should get aborted, setting
    // the node state back to IN_SERVICE on the next run.
    nodeManager.setNodeStatus(dn1, new NodeStatus(IN_SERVICE, HddsProtos.NodeState.HEALTHY));
    monitor.run();
    assertEquals(0, monitor.getTrackedNodeCount());
    assertEquals(IN_SERVICE, nodeManager.getNodeStatus(dn1).getOperationalState());
}

