@BeforeEach
public void setup() {
    conf = new OzoneConfiguration();
    eventQueue = new EventQueue();
    startAdminHandler = new DatanodeAdminMonitorTestUtil.DatanodeAdminHandler();
    eventQueue.addHandler(SCMEvents.START_ADMIN_ON_NODE, startAdminHandler);
    nodeManager = new SimpleMockNodeManager();
    repManager = Mockito.mock(ReplicationManager.class);
    monitor = new DatanodeAdminMonitorImpl(conf, eventQueue, nodeManager, repManager);
    metrics = NodeDecommissionMetrics.create();
    monitor.setMetrics(metrics);
}

/**
 * Test for collecting metric for under replicated containers
 * from nodes in decommissioning and maintenance workflow.
 */
@Test
public void testDecommMonitorCollectUnderReplicated() throws ContainerNotFoundException, NodeNotFoundException {
    DatanodeDetails dn1 = MockDatanodeDetails.createDatanodeDetails("datanode_host1", "/r1/ng1");
    nodeManager.register(dn1, new NodeStatus(HddsProtos.NodeOperationalState.DECOMMISSIONING, HddsProtos.NodeState.HEALTHY));
    Set<ContainerID> containers = new HashSet<>();
    containers.add(ContainerID.valueOf(1));
    // create container with 3 replicas, 2 replicas in-service
    // 1 decommissioned; will result in an under-replicated
    // container
    nodeManager.setContainers(dn1, containers);
    DatanodeAdminMonitorTestUtil.mockGetContainerReplicaCount(repManager, HddsProtos.LifeCycleState.CLOSED, DECOMMISSIONED, IN_SERVICE, IN_SERVICE);
    // Add the node to the monitor, it should have 1 under-replicated
    // container after the first run
    monitor.startMonitoring(dn1);
    monitor.run();
    Assertions.assertEquals(1, metrics.getContainersUnderReplicatedTotal());
    // should have host specific metric collected
    // for datanode_host1
    Assertions.assertEquals(1, metrics.getUnderReplicatedByHost("datanode_host1"));
}

