// Currently invoked by testProcessLayoutVersion.
public void testProcessLayoutVersionLowerMlv(FinalizationCheckpoint currentCheckpoint) throws IOException {
    OzoneConfiguration conf = new OzoneConfiguration();
    SCMStorageConfig scmStorageConfig = mock(SCMStorageConfig.class);
    when(scmStorageConfig.getClusterID()).thenReturn("xyz111");
    EventPublisher eventPublisher = mock(EventPublisher.class);
    HDDSLayoutVersionManager lvm = new HDDSLayoutVersionManager(scmStorageConfig.getLayoutVersion());
    SCMContext nodeManagerContext = SCMContext.emptyContext();
    nodeManagerContext.setFinalizationCheckpoint(currentCheckpoint);
    SCMNodeManager nodeManager = new SCMNodeManager(conf, scmStorageConfig, eventPublisher, new NetworkTopologyImpl(conf), nodeManagerContext, lvm);
    DatanodeDetails node1 = HddsTestUtils.createRandomDatanodeAndRegister(nodeManager);
    verify(eventPublisher, times(1)).fireEvent(NEW_NODE, node1);
    int scmMlv = nodeManager.getLayoutVersionManager().getMetadataLayoutVersion();
    nodeManager.processLayoutVersionReport(node1, LayoutVersionProto.newBuilder().setMetadataLayoutVersion(scmMlv - 1).setSoftwareLayoutVersion(scmMlv).build());
    ArgumentCaptor<CommandForDatanode> captor = ArgumentCaptor.forClass(CommandForDatanode.class);
    if (currentCheckpoint.hasCrossed(FinalizationCheckpoint.MLV_EQUALS_SLV)) {
        // If the mlv equals slv checkpoint passed, datanodes with older mlvs
        // should be instructed to finalize.
        verify(eventPublisher, times(1)).fireEvent(Mockito.eq(DATANODE_COMMAND), captor.capture());
        assertEquals(captor.getValue().getDatanodeId(), node1.getUuid());
        assertEquals(captor.getValue().getCommand().getType(), finalizeNewLayoutVersionCommand);
    } else {
        // SCM has not finished finalizing its mlv, so datanodes with older
        // mlvs should not be instructed to finalize yet.
        verify(eventPublisher, times(0)).fireEvent(Mockito.eq(DATANODE_COMMAND), captor.capture());
    }
}

