@Test
public void testPostProcessingCheck() throws Exception {
    ozoneConfig.set(HDDS_X509_CA_ROTATION_CHECK_INTERNAL, "PT2S");
    ozoneConfig.set(HDDS_X509_RENEW_GRACE_DURATION, "PT20S");
    ozoneConfig.set(HDDS_X509_CA_ROTATION_ACK_TIMEOUT, "PT5S");
    ozoneConfig.set(HDDS_X509_ROOTCA_CERTIFICATE_POLLING_INTERVAL, "PT10S");
    Date date = Calendar.getInstance().getTime();
    date.setMinutes(date.getMinutes() + 5);
    ozoneConfig.set(HDDS_X509_CA_ROTATION_TIME_OF_DAY, String.format("%02d", date.getHours()) + ":" + String.format("%02d", date.getMinutes()) + ":" + String.format("%02d", date.getSeconds()));
    X509Certificate cert = generateX509Cert(ozoneConfig, LocalDateTime.now(), Duration.ofSeconds(90));
    scmCertClient.setCACertificate(cert);
    CertificateCodec certCodec = new CertificateCodec(securityConfig, "scm/sub-ca");
    certCodec.writeCertificate(CertificateCodec.getCertificateHolder(cert));
    rootCARotationManager = new RootCARotationManager(scm);
    rootCARotationManager.setRootCARotationHandler(handler);
    GenericTestUtils.LogCapturer logs = GenericTestUtils.LogCapturer.captureLogs(RootCARotationManager.LOG);
    GenericTestUtils.setLogLevel(RootCARotationManager.LOG, INFO);
    rootCARotationManager.start();
    rootCARotationManager.notifyStatusChanged();
    GenericTestUtils.waitFor(() -> logs.getOutput().contains("No RootCARotationManager " + "configuration found in stateful storage"), 100, 10000);
    when(statefulServiceStateManager.readConfiguration(Mockito.anyString())).thenReturn(new CertInfo.Builder().setX509Certificate(cert).setTimestamp(cert.getNotBefore().getTime()).build().getProtobuf().toByteString());
    logs.clearOutput();
    when(scmContext.isLeader()).thenReturn(false);
    rootCARotationManager.notifyStatusChanged();
    when(scmContext.isLeader()).thenReturn(true);
    rootCARotationManager.notifyStatusChanged();
    GenericTestUtils.waitFor(() -> logs.getOutput().contains("isPostProcessing is true for"), 100, 20000);
    logs.clearOutput();
    when(scmContext.isLeader()).thenReturn(false);
    rootCARotationManager.notifyStatusChanged();
    GenericTestUtils.waitFor(() -> logs.getOutput().contains("disable monitor task"), 100, 20000);
    logs.clearOutput();
    when(scmContext.isLeader()).thenReturn(true);
    rootCARotationManager.notifyStatusChanged();
    GenericTestUtils.waitFor(() -> logs.getOutput().contains("isPostProcessing is true for"), 100, 20000);
    doNothing().when(statefulServiceStateManager).deleteConfiguration(Mockito.anyString());
    GenericTestUtils.waitFor(() -> logs.getOutput().contains("isPostProcessing is false") && logs.getOutput().contains("Stateful configuration is deleted"), 100, 20000);
    verify(statefulServiceStateManager, times(1)).deleteConfiguration(Mockito.anyString());
}

