/**
 * Setups details for HTTP POST request.
 * @param toExcludeList SST file names to be excluded.
 * @throws IOException
 */
private void setupPostMethod(List<String> toExcludeList) throws IOException {
    when(requestMock.getMethod()).thenReturn("POST");
    when(requestMock.getContentType()).thenReturn("multipart/form-data; " + "boundary=" + MULTIPART_FORM_DATA_BOUNDARY);
    // Generate form data
    String crNl = "\r\n";
    String contentDisposition = "Content-Disposition: form-data; name=\"" + OZONE_DB_CHECKPOINT_REQUEST_TO_EXCLUDE_SST + "[]\"" + crNl + crNl;
    String boundary = "--" + MULTIPART_FORM_DATA_BOUNDARY;
    String endBoundary = boundary + "--" + crNl;
    StringBuilder sb = new StringBuilder();
    toExcludeList.forEach(sfn -> {
        sb.append(boundary).append(crNl);
        sb.append(contentDisposition);
        sb.append(sfn).append(crNl);
    });
    sb.append(endBoundary);
    // Use generated form data as input stream to the HTTP request
    InputStream input = new ByteArrayInputStream(sb.toString().getBytes(StandardCharsets.UTF_8));
    ServletInputStream inputStream = Mockito.mock(ServletInputStream.class);
    when(requestMock.getInputStream()).thenReturn(inputStream);
    when(inputStream.read(any(byte[].class), anyInt(), anyInt())).thenAnswer(invocation -> {
        byte[] buffer = invocation.getArgument(0);
        int offset = invocation.getArgument(1);
        int length = invocation.getArgument(2);
        return input.read(buffer, offset, length);
    });
}

