@Test
public void testDownloadSnapshot() throws IOException, AuthenticationException {
    URL omCheckpointUrl = mock(URL.class);
    when(leader.getOMDBCheckpointEndpointUrl(anyBoolean(), anyBoolean())).thenReturn(omCheckpointUrl);
    HttpURLConnection connection = mock(HttpURLConnection.class);
    when(connectionFactory.openConnection(any(URL.class), anyBoolean())).thenReturn(connection);
    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    when(connection.getOutputStream()).thenReturn(outputStream);
