    assertEquals(SnapshotDiffResponse.JobStatus.IN_PROGRESS, snapshotDiffResponse.getJobStatus());
    diffJob = snapDiffJobMap.get(diffJobKey);
    assertNotNull(diffJob);
    assertEquals(SnapshotDiffResponse.JobStatus.IN_PROGRESS, diffJob.getStatus());
    jobList = snapshotDiffManager.getSnapshotDiffJobList(volumeName, bucketName, jobStatus, listAll);
    // When listAll is true, jobStatus is ignored.
    // If the job is IN_PROGRESS or listAll is used,
    // there should be a response.
    // Otherwise, response list should be empty.
    if (containsJob) {
        assertTrue(jobList.contains(diffJob));
    } else {
        assertTrue(jobList.isEmpty());
    }
}

