/**
 * Tests that IN_PROGRESS jobs are submitted to the executor on the service
 * startup.
 */
@Test
public void testLoadJobsOnStartUp() throws Exception {
    for (int i = 0; i < snapshotInfoList.size(); i++) {
        uploadSnapshotDiffJobToDb(snapshotInfo, snapshotInfoList.get(i), snapDiffJobs.get(i));
    }
    SnapshotDiffManager spy = spy(snapshotDiffManager);
    doAnswer(invocation -> {
        SnapshotDiffJob diffJob = getSnapshotDiffJobFromDb(snapshotInfo, snapshotInfoList.get(1));
        diffJob.setTotalDiffEntries(1L);
        diffJob.setStatus(DONE);
        uploadSnapshotDiffJobToDb(snapshotInfo, snapshotInfoList.get(1), diffJob);
        return null;
    }).when(spy).generateSnapshotDiffReport(anyString(), anyString(), eq(VOLUME_NAME), eq(BUCKET_NAME), eq(snapshotInfo.getName()), eq(snapshotInfoList.get(1).getName()), eq(false), eq(false));
