@ParameterizedTest
@ValueSource(ints = { 1, 2, 5, 10, 100, 1000, 10000 })
public void testGetDeltaFilesWithDag(int numberOfFiles) throws IOException {
    UUID snap1 = UUID.randomUUID();
    UUID snap2 = UUID.randomUUID();
    String diffDir = Files.createTempDirectory("snapdiff_dir").toString();
    Set<String> randomStrings = IntStream.range(0, numberOfFiles).mapToObj(i -> RandomStringUtils.randomAlphabetic(10)).collect(Collectors.toSet());
    when(differ.getSSTDiffListWithFullPath(any(DifferSnapshotInfo.class), any(DifferSnapshotInfo.class), eq(diffDir))).thenReturn(Lists.newArrayList(randomStrings));
    ReferenceCounted<IOmMetadataReader, SnapshotCache> rcFromSnapshot = snapshotCache.get(snap1.toString());
    ReferenceCounted<IOmMetadataReader, SnapshotCache> rcToSnapshot = snapshotCache.get(snap2.toString());
    OmSnapshot fromSnapshot = (OmSnapshot) rcFromSnapshot.get();
    OmSnapshot toSnapshot = (OmSnapshot) rcToSnapshot.get();
    SnapshotInfo fromSnapshotInfo = getMockedSnapshotInfo(snap1);
    SnapshotInfo toSnapshotInfo = getMockedSnapshotInfo(snap2);
    when(jobTableIterator.isValid()).thenReturn(false);
    Set<String> deltaFiles = snapshotDiffManager.getDeltaFiles(fromSnapshot, toSnapshot, Arrays.asList("cf1", "cf2"), fromSnapshotInfo, toSnapshotInfo, false, Collections.emptyMap(), diffDir);
    assertEquals(randomStrings, deltaFiles);
    rcFromSnapshot.close();
    rcToSnapshot.close();
}

