@Test
public void testValidateAndUpdateCache() throws IOException {
    // Happy path
    final String tenantId = UUID.randomUUID().toString();
    OMRequest originalRequest = OMRequestTestUtils.createTenantRequest(tenantId, false);
    OMTenantCreateRequest omTenantCreateRequest = Mockito.spy(new OMTenantCreateRequest(originalRequest));
    Mockito.doReturn("username").when(omTenantCreateRequest).getUserName();
    // First creation should be successful
    OMRequest modifiedRequest = omTenantCreateRequest.preExecute(ozoneManager);
    omTenantCreateRequest = new OMTenantCreateRequest(modifiedRequest);
    long txLogIndex = 1L;
    OMClientResponse omClientResponse = omTenantCreateRequest.validateAndUpdateCache(ozoneManager, txLogIndex, ozoneManagerDoubleBufferHelper);
    OMResponse omResponse = omClientResponse.getOMResponse();
    Assert.assertNotNull(omResponse.getCreateTenantResponse());
    Assert.assertEquals(Status.OK, omResponse.getStatus());
    Assert.assertNotNull(omMetadataManager.getVolumeTable().get(omMetadataManager.getVolumeKey(tenantId)));
}

