@Test
public void testLeadershipCheckinRetrievePassword() throws Exception {
    secretManager = createSecretManager(conf, TOKEN_MAX_LIFETIME, expiryTime, TOKEN_REMOVER_SCAN_INTERVAL);
    Mockito.doThrow(new OMNotLeaderException(RaftPeerId.valueOf("om"))).when(om).checkLeaderStatus();
    OzoneTokenIdentifier identifier = new OzoneTokenIdentifier();
    try {
        secretManager.retrievePassword(identifier);
    } catch (Exception e) {
        Assert.assertEquals(SecretManager.InvalidToken.class, e.getClass());
        Assert.assertEquals(OMNotLeaderException.class, e.getCause().getClass());
    }
    Mockito.doThrow(new OMLeaderNotReadyException("Leader not ready")).when(om).checkLeaderStatus();
    try {
        secretManager.retrievePassword(identifier);
    } catch (Exception e) {
        Assert.assertEquals(SecretManager.InvalidToken.class, e.getClass());
        Assert.assertEquals(OMLeaderNotReadyException.class, e.getCause().getClass());
    }
    Mockito.doNothing().when(om).checkLeaderStatus();
    try {
        secretManager.retrievePassword(identifier);
    } catch (Exception e) {
        Assert.assertEquals(SecretManager.InvalidToken.class, e.getClass());
        Assert.assertNull(e.getCause());
    }
}

