private void closeContainer(long containerID) throws IOException {
    if (containerID >= 1L && containerID <= 5L) {
        ContainerInfo closedContainer = new ContainerInfo.Builder().setContainerID(containerID).setReplicationConfig(RatisReplicationConfig.getInstance(ReplicationFactor.ONE)).setState(LifeCycleState.CLOSED).setOwner("test").setPipelineID(pipeline.getId()).build();
        ContainerWithPipeline containerWithPipeline = new ContainerWithPipeline(closedContainer, pipeline);
        when(mockScmServiceProvider.getContainerWithPipeline(containerID)).thenReturn(containerWithPipeline);
        cpw.set((int) containerID - 1, containerWithPipeline);
    } else if (containerID >= 6L && containerID <= 10L) {
        ContainerInfo closedContainer = new ContainerInfo.Builder().setContainerID(containerID).setReplicationConfig(RatisReplicationConfig.getInstance(ReplicationFactor.ONE)).setState(LifeCycleState.CLOSED).setOwner("test").setPipelineID(pipeline2.getId()).build();
        ContainerWithPipeline containerWithPipeline = new ContainerWithPipeline(closedContainer, pipeline2);
        when(mockScmServiceProvider.getContainerWithPipeline(containerID)).thenReturn(containerWithPipeline);
        cpw.set((int) containerID - 1, containerWithPipeline);
    }
    when(mockScmServiceProvider.getExistContainerWithPipelinesInBatch(containerIDs)).thenReturn(cpw);
    updateContainerReport(containerID);
}

