@Test
public void writeWithHsync() throws IOException {
    class SyncableByteArrayOutputStream extends ByteArrayOutputStream implements Syncable, StreamCapabilities {

        @Override
        public void hflush() throws IOException {
        }

        @Override
        public void hsync() throws IOException {
        }

        @Override
        public boolean hasCapability(String capability) {
            return true;
        }
    }
    ContentGenerator generator = new ContentGenerator(20, 8, 3, ContentGenerator.SyncOptions.HSYNC);
    SyncableByteArrayOutputStream syncable = new SyncableByteArrayOutputStream();
    SyncableByteArrayOutputStream spySyncable = spy(syncable);
    generator.write(spySyncable);
    verify(spySyncable, times(8)).hsync();
    generator = new ContentGenerator(20, 8, 3);
    spySyncable = spy(syncable);
    generator.write(spySyncable);
    verify(spySyncable, times(0)).hsync();
}

