@Before
public void setupMock() {
    numberOfKeysAdded = new AtomicLong(0L);
    currentValue = numberOfKeysAdded::get;
    stream = mock(PrintStream.class);
}

@Test
public void testWithRunnable() {
    long maxValue = 10L;
    ProgressBar progressbar = new ProgressBar(stream, maxValue, currentValue, true, () -> "");
    Runnable task = () -> LongStream.range(0, maxValue).forEach(counter -> numberOfKeysAdded.getAndIncrement());
    progressbar.start();
    task.run();
    progressbar.shutdown();
    verify(stream, atLeastOnce()).print(anyChar());
    verify(stream, atLeastOnce()).print(anyString());
}

